.ds .ds-token-text { align-items:baseline; font-family:var(--p-font); }
.ds .ds-token-text [data-token="sm"] { font-size:var(--p-text-sm); }
.ds .ds-token-text [data-token="body"] { font-size:var(--p-text-body); }
.ds .ds-token-text [data-token="title"] { font-size:var(--p-text-title); }
.ds .ds-token-text [data-token="heading"] { font-size:var(--p-text-heading); }
.ds .ds-token-text [data-token="display"] { font-size:var(--p-text-display); }
